package discovery

import (
	"strings"
	"testing"
)

func TestParseResolvConf(t *testing.T) {
	fixture := `
# Generated by NetworkManager
nameserver 1.1.1.1
nameserver 8.8.8.8
nameserver 2001:4860:4860::8888
nameserver invalid.ip.address

search example.com corp.example.com
domain internal.net
`
	config, err := ParseResolvConf(strings.NewReader(fixture))
	if err != nil {
		t.Fatalf("ParseResolvConf() error = %v", err)
	}

	expectedServers := []string{
		"1.1.1.1",
		"8.8.8.8",
		"2001:4860:4860::8888",
	}

	if len(config.Servers) != len(expectedServers) {
		t.Fatalf("servers count = %d, want %d", len(config.Servers), len(expectedServers))
	}
	for i, s := range expectedServers {
		if config.Servers[i] != s {
			t.Errorf("server[%d] = %q, want %q", i, config.Servers[i], s)
		}
	}

	expectedSearch := []string{"example.com", "corp.example.com"}
	if len(config.SearchDomains) != len(expectedSearch) {
		t.Fatalf("search domains count = %d, want %d", len(config.SearchDomains), len(expectedSearch))
	}
	for i, d := range expectedSearch {
		if config.SearchDomains[i] != d {
			t.Errorf("search domain[%d] = %q, want %q", i, config.SearchDomains[i], d)
		}
	}
}

func TestParseResolvConfEmpty(t *testing.T) {
	config, err := ParseResolvConf(strings.NewReader("# only comments\n; another comment\n"))
	if err != nil {
		t.Fatalf("ParseResolvConf() error = %v", err)
	}
	if len(config.Servers) != 0 {
		t.Fatalf("expected 0 servers, got %d", len(config.Servers))
	}
}

func TestDiscoverResolvers(t *testing.T) {
	config, err := DiscoverResolvers()
	if err != nil {
		t.Logf("DiscoverResolvers() returned error in current environment (may have no DNS configured): %v", err)
		return
	}
	if len(config.Servers) == 0 {
		t.Fatal("DiscoverResolvers() returned 0 servers without an error")
	}
	t.Logf("Discovered %d servers via %s: %v", len(config.Servers), config.Source, config.Servers)
}
